/* BERTH.A RC221 — Kids · Coelho de Nuvem · pack 5 acessórios × 3 cores
   Patch incremental sobre RC220. Preserva trilha de 30 dias e Gato Neblina.
*/
(function(){
  'use strict';
  const BUILD='RC221';
  const PALS=['nevoa','coral','misto'];
  const VARIANT_PREFIX='bertha.kids.accessory.variant.';
  const IDS={
    'mist_mist_v1_rabbit_head_0': 'head',
    'mist_mist_v1_rabbit_neck_1': 'neck',
    'mist_mist_v1_rabbit_eyes_2': 'eyes',
    'mist_mist_v1_rabbit_back_3': 'back',
    'mist_mist_v1_rabbit_special_4': 'special'
  };
  const NAMES={
    'mist_mist_v1_rabbit_head_0': 'Boné de Nuvem',
    'mist_mist_v1_rabbit_neck_1': 'Bandana de Bruma',
    'mist_mist_v1_rabbit_eyes_2': 'Óculos de Grau Nuvem',
    'mist_mist_v1_rabbit_back_3': 'Mochila Saltinho',
    'mist_mist_v1_rabbit_special_4': 'Pingente Coelho de Nuvem'
  };
  const ASSETS={
    'head-nevoa': 'data:image/png;base64,',
    'head-coral': 'data:image/png;base64,',
    'head-misto': 'data:image/png;base64,',
    'neck-nevoa': 'data:image/png;base64,',
    'neck-coral': 'data:image/png;base64,',
    'neck-misto': 'data:image/png;base64,',
    'eyes-nevoa': 'data:image/png;base64,',
    'eyes-coral': 'data:image/png;base64,',
    'eyes-misto': 'data:image/png;base64,',
    'back-nevoa': 'data:image/png;base64,',
    'back-coral': 'data:image/png;base64,',
    'back-misto': 'data:image/png;base64,',
    'special-nevoa': 'data:image/png;base64,',
    'special-coral': 'data:image/png;base64,',
    'special-misto': 'data:image/png;base64,'
  };
  const store=()=>window.berthaHmlStorage||window.localStorage;
  function selectedKid(){
    const sel=document.querySelector('#r152KidSel');
    if(sel&&sel.value)return String(sel.value);
    if(window.__rc209Member!=null)return String(window.__rc209Member);
    return 'default';
  }
  function variantFor(aid){
    const n=Number(store().getItem(VARIANT_PREFIX+selectedKid()+'.'+aid));
    return Number.isFinite(n)?Math.max(0,Math.min(2,n)):2;
  }
  function srcFor(aid){const kind=IDS[aid];return kind?ASSETS[kind+'-'+PALS[variantFor(aid)]]:'';}
  function stamp(){
    document.documentElement.dataset.berthaBuild=BUILD;
    document.documentElement.dataset.berthaIndex=BUILD;
    document.title='BERTH.A · Homologação '+BUILD;
    const idx=document.getElementById('rc157IndexBadge'); if(idx)idx.textContent='INDEX · '+BUILD;
    document.querySelectorAll('body *').forEach(el=>{if(el.children.length===0&&/^HML\s*·\s*RC\d+/i.test((el.textContent||'').trim()))el.textContent='HML · '+BUILD;});
  }
  function patch(root=document){
    root.querySelectorAll('.rc209-acc-proxy[data-acc]').forEach(proxy=>{
      const aid=proxy.getAttribute('data-acc'); if(!IDS[aid])return;
      const src=srcFor(aid); proxy.classList.add('rc221-rabbit-asset'); proxy.dataset.rc221='1';
      let im=proxy.querySelector('img'); if(!im){proxy.replaceChildren();im=document.createElement('img');im.alt='';im.loading='eager';im.decoding='async';proxy.appendChild(im);}
      if(im.getAttribute('src')!==src)im.setAttribute('src',src);
      const card=proxy.closest('.r197-acc');
      if(card){const s=card.querySelector('strong');if(s&&NAMES[aid])s.textContent=NAMES[aid];}
    });
    stamp();
  }
  const style=document.createElement('style');style.id='rc221-rabbit-assets-style';style.textContent=`
    .r197-acc-art .rc221-rabbit-asset{display:flex!important;align-items:center!important;justify-content:center!important;width:100%!important;height:100%!important;min-height:136px!important;overflow:visible!important;background:transparent!important}
    .r197-acc-art .rc221-rabbit-asset img{display:block!important;width:98%!important;height:136px!important;object-fit:contain!important;object-position:center!important;filter:none!important;transform:none!important}
    .r197-acc:has(.rc221-rabbit-asset) .r197-acc-art{min-height:144px!important;overflow:visible!important}
  `;document.head.appendChild(style);
  Object.values(ASSETS).forEach(src=>{const i=new Image();i.decoding='async';i.src=src;});
  let raf=0;const schedule=()=>{if(raf)return;raf=requestAnimationFrame(()=>{raf=0;patch(document);});};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',schedule,{once:true});else schedule();
  window.addEventListener('pageshow',schedule);
  window.addEventListener('hashchange',()=>setTimeout(schedule,30));
  document.addEventListener('click',e=>{if(e.target.closest('[data-rc209variant],[data-r152pet],#rc208PetSel,#rc208CollectionSel'))setTimeout(schedule,30);},true);
  new MutationObserver(schedule).observe(document.documentElement,{childList:true,subtree:true});
})();
